age 2026-01-05 at 3.18.56 PM.jpeg\"},{\"id\":\"1767703775498\",\"src\":\"/images/upload/logoSystem/1767703777371_7zmq6iwtggx.jpg\",\"alt\":\"SW Tech Media Private Limited\",\"fileName\":\"1753861044970_Logo (1).jpg\"},{\"id\":\"1767703799958\",\"src\":\"/images/upload/logoSystem/1767706344581_r2hogdzeeq.jpeg\",\"alt\":\"Hartalkar Innovations Private limited\",\"fileName\":\"1753861044970_hartalkar_industries_logo.jpeg\"},{\"id\":\"1767704388752\",\"src\":\"/images/upload/logoSystem/1767704390622_9em3cgj555.jpg\",\"alt\":\"Glampowheel\",\"fileName\":\"1753861044970_Glampowheel.jpg\"},{\"id\":\"1767704402641\",\"src\":\"/images/upload/logoSystem/1767704404528_alpivnivq25.png\",\"alt\":\"Harshhasthkala\",\"fileName\":\"1753861044970_harshhasthkala.png\"},{\"id\":\"1767704413702\",\"src\":\"/images/upload/logoSystem/1767704415575_rkfofjkh12j.webp\",\"alt\":\"Toss Solution\",\"fileName\":\"1753861044970_Toss solution.webp\"}]', '2026-01-14 09:09:08', '2026-01-14 09:09:08');
